import { beforeEach, describe, test } from '@e2e-dev/web';
import { expect } from 'e2e';

describe('create todo form', () => {
  beforeEach(async ({ app }) => {
    await app.open('/todos');
  });

  test('adds a todo', async ({ agent, screen }) => {
    await agent.act('add a new todo titled "Buy milk"');

    await expect(screen.getByRole('checkbox', 'Buy milk')).toBeVisible();
    await expect(screen.getByRole('status', 'Remaining')).toHaveText('1 remaining');

    await agent.assert('the "New todo" input is empty');
    await agent.assert('"Buy milk" appears in the list as not done');
  });

  test('ignores an empty todo', async ({ agent, screen }) => {
    await agent.act('click Add without typing anything');

    await expect(screen.getByRole('listitem')).toHaveCount(0);

    await agent.assert("no todo is visible", { vision: true });
  });
});

import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  /* config options here */
  experimental: {
    agentFeedback: true,
  },
  cacheComponents: true,
  partialPrefetching: true,
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;

import type { E2EConfig } from 'e2e';
import { web } from '@e2e-dev/web';
import { gateway } from 'ai';

export default {
  // The Vercel AI Gateway serves the model id and reads AI_GATEWAY_API_KEY, or the OIDC token of a linked Vercel project.
  agents: {
    default: {
      model: gateway('openai/gpt-6-luna-fast'),
      system: 'You are a thorough QA agent. Verify every outcome.',
    },
  },
  targets: [{
    engine: web(),
    app: {
      url: process.env.APP_URL ?? 'http://localhost:3000',
      // Or let the runner start the dev server:
      // command: { executable: 'npm', args: ['run', 'dev'] },
    },
  }],
} satisfies E2EConfig;

{
  "compilerOptions": {
    "target": "ES2017",
    "lib": [
      "dom",
      "dom.iterable",
      "esnext"
    ],
    "allowJs": true,
    "skipLibCheck": true,
    "strict": true,
    "noEmit": true,
    "esModuleInterop": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "resolveJsonModule": true,
    "isolatedModules": true,
    "jsx": "react-jsx",
    "incremental": true,
    "plugins": [
      {
        "name": "next"
      }
    ],
    "paths": {
      "@/*": [
        "./*"
      ]
    }
  },
  "include": [
    "next-env.d.ts",
    "**/*.ts",
    "**/*.tsx",
    ".next/types/**/*.ts",
    ".next/dev/types/**/*.ts",
    "**/*.mts"
